       /**
        * MitraUtama Table Stylesheet (mitrautama-tabel.css)
        * Awalan kelas dan atribut: mitrautama-
        */
       
       .mitrautama-table-container {
           width: 100%;
           overflow-x: auto;
           background: var(--mu-bg-card, #ffffff);
           border: 1px solid var(--mu-border, #e2e8f0);
           border-radius: 12px;
           box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
           margin-bottom: 20px;
       }
       
       .mitrautama-table {
           width: 100%;
           border-collapse: separate;
           border-spacing: 0;
           font-size: 0.875rem;
           color: var(--mu-text-main, #0f172a);
       }
       
       .mitrautama-table thead th {
           background: var(--mu-bg-card-subtle, #f8fafc);
           color: var(--mu-text-muted, #64748b);
           font-weight: 600;
           text-transform: uppercase;
           font-size: 0.75rem;
           letter-spacing: 0.05em;
           padding: 12px 16px;
           border-bottom: 2px solid var(--mu-border, #e2e8f0);
           text-align: left;
           white-space: nowrap;
       }
       
       .mitrautama-table tbody tr {
           transition: background-color 0.15s ease, transform 0.15s ease;
       }
       
       .mitrautama-table tbody tr:hover {
           background-color: rgba(2, 132, 199, 0.04);
       }
       
       .mitrautama-table tbody td {
           padding: 12px 16px;
           border-bottom: 1px solid var(--mu-border, #e2e8f0);
           vertical-align: middle;
       }
       
       .mitrautama-table tbody tr:last-child td {
           border-bottom: none;
       }
       
       /* Status Badges */
       .mitrautama-badge {
           display: inline-flex;
           align-items: center;
           gap: 4px;
           padding: 3px 8px;
           border-radius: 9999px;
           font-size: 0.75rem;
           font-weight: 600;
           line-height: 1.2;
       }
       
       .mitrautama-badge-success {
           background: #dcfce7;
           color: #15803d;
       }
       
       .mitrautama-badge-danger {
           background: #fee2e2;
           color: #b91c1c;
       }
       
       .mitrautama-badge-warning {
           background: #fef3c7;
           color: #b45309;
       }
       
       .mitrautama-badge-info {
           background: #e0f2fe;
           color: #0369a1;
       }
       
       .mitrautama-badge-secondary {
           background: #f1f5f9;
           color: #475569;
       }
       
       /* Dark mode overrides for table */
       [data-theme="dark"] .mitrautama-table-container {
           background: #151e32;
           border-color: #1e293b;
           box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.4);
       }
       
       [data-theme="dark"] .mitrautama-table thead th {
           background: #0f172a;
           color: #94a3b8;
           border-bottom-color: #1e293b;
       }
       
       [data-theme="dark"] .mitrautama-table tbody tr:hover {
           background-color: rgba(56, 189, 248, 0.08);
       }
       
       [data-theme="dark"] .mitrautama-table tbody td {
           border-bottom-color: #1e293b;
           color: #f8fafc;
       }
       
       [data-theme="dark"] .mitrautama-badge-success {
           background: rgba(34, 197, 94, 0.2);
           color: #4ade80;
       }
       
       [data-theme="dark"] .mitrautama-badge-danger {
           background: rgba(239, 68, 68, 0.2);
           color: #f87171;
       }
       
       [data-theme="dark"] .mitrautama-badge-info {
           background: rgba(56, 189, 248, 0.2);
           color: #38bdf8;
       }
       
       [data-theme="dark"] .mitrautama-badge-secondary {
           background: #1e293b;
           color: #94a3b8;
       }
 
